        // Check if y is divisible by x
        if (y % x != 0) {
            System.out.println(0);
            return;
        }

        long n = y / x;

        // We need to find the number of divisors d of n such that:
        // a = x * d
        // b = x * (n / d)
        // and l <= a <= r and l <= b <= r
        // This implies:
        // l <= x * d <= r  =>  ceil(l/x) <= d <= floor(r/x)
        // l <= x * (n/d) <= r =>  ceil(l/x) <= n/d <= floor(r/x)

        // Let L = ceil(l/x) and R = floor(r/x)
        // We need d such that:
        // 1. d divides n
        // 2. L <= d <= R
        // 3. L <= n/d <= R  =>  n/R <= d <= n/L

        // So d must be in the intersection of [L, R] and [n/R, n/L]
        // Let low = max(L, n/R)
        // Let high = min(R, n/L)
        // We need to count the number of divisors d of n such that low <= d <= high.

        long L = (l + x - 1) / x; // ceil(l/x)
        long R = r / x;           // floor(r/x)

        // If L > R, there are no possible values for d
        if (L > R) {
            System.out.println(0);
            return;
        }

        // The condition for n/d is L <= n/d <= R
        // This is equivalent to n/R <= d <= n/L
        // Note: n/R is floor division? No, we need real number bounds.
        // n/d >= L  => d <= n/L
        // n/d <= R  => d >= n/R
        // Since d is an integer, the range for d from the second condition is [ceil(n/R), floor(n/L)]

        long low = Math.max(L, (n + R - 1) / R); // max(L, ceil(n/R))
        long high = Math.min(R, n / L);           // min(R, floor(n/L))

        if (low > high) {
            System.out.println(0);
            return;
        }

        // Now we need to count the number of divisors d of n such that low <= d <= high.
        // We can iterate up to sqrt(n) to find divisors.
        // For each divisor i of n, we check if i is in [low, high] and if n/i is in [low, high].

        long count = 0;
        long sqrtN = (long) Math.sqrt(n);

