            if (n % i == 0) {
                long d1 = i;
                long d2 = n / i;

                if (d1 >= low && d1 <= high) {
                    count++;
                }
                if (d2 >= low && d2 <= high) {
                    count++;
                }
            }
        }

        System.out.println(count);
    }
